18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
34	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.web.bind.annotation.CrossOrigin;
46	import org.springframework.web.bind.annotation.RequestMapping;
47	import org.springframework.web.bind.annotation.RestController;
48	import org.springframework.web.util.UriComponentsBuilder;
49	
50	import jakarta.transaction.Transactional;
51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    private final TelephoneNormalizer telephoneNormalizer;
70	
71	    public OwnerRestControllerV1(ClinicService clinicService,
72	                                 OwnerMapper ownerMapper,
73	                                 PetMapper petMapper,
74	                                 VisitMapper visitMapper,
75	                                 TelephoneNormalizer telephoneNormalizer) {
76	        this.clinicService = clinicService;
77	        this.ownerMapper = ownerMapper;
78	        this.petMapper = petMapper;
79	        this.visitMapper = visitMapper;
80	        this.telephoneNormalizer = telephoneNormalizer;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        validateRequiredFields(ownerFieldsDto);
112	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
113	        ownerFieldsDto.setTelephone(telephone);
114	        requireUniqueTelephone(telephone);
115	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
116	        if (ownerFieldsDto.getRegistrationDate() == null) {
117	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
118	        }
119	        HttpHeaders headers = new HttpHeaders();
120	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
121	        this.clinicService.saveOwner(owner);
122	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
123	        headers.setLocation(UriComponentsBuilder.newInstance()
124	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
125	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
126	    }
127	
128	    /**
129	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
130	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
131	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
132	     *
133	     * @param ownerFieldsDto the owner payload to validate
134	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
135	     */
136	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
137	        List<String> missingFields = new ArrayList<>();
138	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
139	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
140	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
141	        requireText(missingFields, "city", ownerFieldsDto.getCity());
142	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
143	        if (!missingFields.isEmpty()) {
144	            throw new MissingOwnerFieldsException(missingFields);
145	        }
146	    }
147	
148	    private void requireText(List<String> missingFields, String fieldName, String value) {
149	        if (value == null || value.isBlank()) {
150	            missingFields.add(fieldName);
151	        }
152	    }
153	
154	    /**
155	     * Normalizes an optional owner email. A syntactically valid address is already enforced by Bean Validation on the
156	     * request payload, so this only canonicalizes the value that gets stored and returned by lower-casing it. A missing
157	     * (blank or {@code null}) email is left untouched, since the field is optional.
158	     *
159	     * @param email the raw email value from the request, may be {@code null}
160	     * @return the lower-cased email, or the original value when none was supplied
161	     */
162	    private String normalizeEmail(String email) {
163	        if (email == null || email.isBlank()) {
164	            return email;
165	        }
166	        return email.toLowerCase();
167	    }
168	
169	    /**
170	     * Rejects creating an owner whose normalized telephone is already used by another owner. Existing owners' stored
171	     * telephones are canonicalized the same way before comparison, so the rule holds regardless of how their number was
172	     * originally formatted.
173	     *
174	     * @param telephone the normalized telephone of the owner being created
175	     * @throws DuplicateTelephoneException if any existing owner already uses the same normalized telephone
176	     */
177	    private void requireUniqueTelephone(String telephone) {
178	        boolean inUse = this.clinicService.findAllOwners().stream()
179	            .map(existing -> telephoneNormalizer.canonicalize(existing.getTelephone()))
180	            .anyMatch(telephone::equals);
181	        if (inUse) {
182	            throw new DuplicateTelephoneException("telephone is already in use by another owner");
183	        }
184	    }
185	
186	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
187	    @Override
188	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
189	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
190	        if (currentOwner == null) {
191	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
192	        }
193	        currentOwner.setAddress(ownerFieldsDto.getAddress());
194	        currentOwner.setCity(ownerFieldsDto.getCity());
195	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
196	        currentOwner.setLastName(ownerFieldsDto.getLastName());
197	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
198	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
199	        this.clinicService.saveOwner(currentOwner);
200	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Transactional
205	    @Override
206	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
207	        Owner owner = this.clinicService.findOwnerById(ownerId);
208	        if (owner == null) {
209	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
210	        }
211	        this.clinicService.deleteOwner(owner);
212	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
213	    }
214	
215	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
216	    @Override
217	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
218	        Owner owner = this.clinicService.findOwnerById(ownerId);
219	        if (owner == null) {
220	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
221	        }
222	        HttpHeaders headers = new HttpHeaders();
223	        Pet pet = petMapper.toPet(petFieldsDto);
224	        owner.setId(ownerId);
225	        pet.setOwner(owner);
226	        pet.getType().setName(null);
227	        this.clinicService.savePet(pet);
228	        PetDto petDto = petMapper.toPetDto(pet);
229	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
230	            .buildAndExpand(pet.getId()).toUri());
231	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
232	    }
233	
234	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
235	    @Override
236	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
237	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
238	        if (currentOwner != null) {
239	            Pet currentPet = this.clinicService.findPetById(petId);
240	            if (currentPet != null) {
241	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
242	                currentPet.setName(petFieldsDto.getName());
